#include <iostream>
#include <string>
#include <vector>
using namespace std;
long long fact(int n) {
    if (n == 0)
        return 1;
    return n * fact(n - 1);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fact(4);
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;
void generate(string s, int n) {
    if ((int)s.size() == n) {
        cout << s << "\n";
        return;
    }
    generate(s + "0", n);
    generate(s + "1", n);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    generate("", 2);
}

