advanced.solutionCode:
#include <iostream>
#include <string>
#include <vector>
using namespace std;
void gen(string s, int n) {
    if ((int)s.size() == n) {
        cout << s << "\n";
        return;
    }
    gen(s + "0", n);
    if (s.empty() || s.back() != '1')
        gen(s + "1", n);
}
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    gen("", n);
}
